<?php $pageTitle='Registrasi Pasien Lama'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Petugas Registrasi','Administrator SIMRS']);$query='';$results=[];$searched=false;$msg='';$error='';$clinics=$pdo->query("SELECT id,name FROM master_clinics WHERE active=1 ORDER BY name")->fetchAll();
if(isset($_POST['search'])){$query=trim($_POST['q']??'');$searched=true;$s=$pdo->prepare("SELECT * FROM patients WHERE medical_record_no=? OR nik=? OR LOWER(name) LIKE LOWER(?) ORDER BY name LIMIT 12");$s->execute([$query,$query,'%'.$query.'%']);$results=$s->fetchAll();}
if(isset($_POST['register'])){try{$id=(int)$_POST['patient_id'];$clinicId=(int)$_POST['clinic_id'];$p=$pdo->prepare('SELECT * FROM patients WHERE id=?');$p->execute([$id]);$patient=$p->fetch();$c=$pdo->prepare('SELECT * FROM master_clinics WHERE id=? AND active=1');$c->execute([$clinicId]);$clinic=$c->fetch();if(!$patient||!$clinic)throw new RuntimeException('Data pasien atau unit layanan tidak tersedia.');$queue=next_queue($pdo,$clinicId);$v=$pdo->prepare("INSERT INTO visits(patient_id,clinic_id,clinic,doctor,queue_no,service_type,status,notes) VALUES(?,?,?,?,?,'Rawat Jalan','Terdaftar',?)");$v->execute([$id,$clinicId,$clinic['name'],trim($_POST['doctor']??''),$queue,'Registrasi pasien lama']);$vid=(int)$pdo->lastInsertId();audit($pdo,'CREATE_VISIT','visits',$vid,'Registrasi pasien lama '.$patient['medical_record_no'].' • antrean '.$queue);$msg='Kunjungan berhasil dibuat. Nomor antrean '.$queue.' untuk '.$clinic['name'].'.';}catch(Throwable $e){$error=$e->getMessage();}}
include 'partials/header.php'; ?>
<?php if($msg): ?><div class="alert">✓ <?=e($msg)?></div><?php endif; ?><?php if($error): ?><div class="alert error">⚠ <?=e($error)?></div><?php endif; ?>
<div class="card"><div class="card-title"><div><h2>Pencarian pasien</h2><p>Cari dengan nomor RM, NIK, atau nama pasien sebelum membuat kunjungan.</p></div><span class="badge blue">Pasien Lama</span></div><form method="post" class="search"><input name="q" value="<?=e($query)?>" placeholder="Nomor RM / NIK / nama pasien" required><button class="btn">Cari</button></form></div>
<?php if($searched): ?><div class="card mt"><div class="card-title"><div><h2>Hasil pencarian</h2><p><?=count($results)?> data ditemukan</p></div></div><?php if(!$results): ?><div class="alert warning">Pasien tidak ditemukan. Periksa kembali kata kunci atau gunakan Registrasi Pasien Baru.</div><?php endif; ?><?php foreach($results as $p): ?><div class="patient-card"><div class="patient-head"><div><div class="patient-name"><?=e($p['name'])?></div><div class="patient-meta"><b><?=e($p['medical_record_no'])?></b> • NIK <?=e($p['nik'])?><br><?=e(date('d/m/Y',strtotime($p['dob'])))?> • <?=($p['gender']==='L'?'Laki-laki':'Perempuan')?> • <?=e($p['phone']?:'Telepon belum diisi')?></div></div><span class="badge <?=((int)$p['duplicate_flag']?'red':'green')?>"><?=((int)$p['duplicate_flag']?'Validasi Identitas':'Data Aktif')?></span></div><form method="post" style="margin-top:12px"><input type="hidden" name="patient_id" value="<?=$p['id']?>"><div class="form-grid"><div><label>Unit layanan</label><select name="clinic_id" required><option value="">Pilih unit</option><?php foreach($clinics as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select></div><div><label>Dokter tujuan</label><input name="doctor" placeholder="Sesuai jadwal klinik"></div><div class="full"><label>Keperluan kunjungan</label><textarea name="visit_note" placeholder="Kontrol, konsultasi, pemeriksaan, atau kebutuhan administrasi"></textarea></div></div><div style="margin-top:12px;display:flex;justify-content:flex-end"><button class="btn">Buat Kunjungan & Antrean</button></div></form></div><?php endforeach; ?></div><?php endif; ?>
<?php include 'partials/footer.php'; ?>
